import React, { memo, useEffect, useMemo } from 'react';
import axios from 'axios';
import { useQuery } from 'react-query';
import styled from 'styled-components';
import { useSelector, useDispatch } from 'react-redux';
import { fetchPlanHatApi } from 'redux/actions/common';
import { useRouter } from 'next/router';
import { uniq } from 'lodash';
import { isDateOlderThanMonths } from 'Utils/DateUtils'
import {
  useSessionBugInfo,
  useSessionAppLogs,
} from 'components/features/sessions/hooks/useSessionDetail';
import {
  useSessionScreenList,
  useAppScreenList,
} from 'components/features/sessions/hooks/useSessionDetailsSidebar';
import {
  setSelectedScreens,
  setScreenList,
} from 'redux/actions/video'
import { mappedSegmentType } from 'Utils/helpers/commonUtils';
import SessionVideo from 'components/shared/Sessions/Video';
import SessionLoader from 'components/shared/Sessions/Video/Loader';
import SessionDetailsHeader from 'components/shared/Sessions/Video/Header/SessionDetailsHeader';
import { useScreenLayoutContext, useSessionHeader, useSessionTimeLine } from 'components/shared/Sessions/Context';
import StackTrace from 'components/shared/Sessions/Video/Header/StackTrace';
import BugTrace from 'components/shared/Sessions/Video/Header/BugTrace';
import AnrTrace from 'components/shared/Sessions/Video/Header/AnrTrace';
import { useRestrictionContext } from 'components/IntegratePages/layout/context/restrictionContext';
import { useFetchAppSetting } from 'components/features/setting/useSettingPage';
import { useFeatureFlag } from 'uxcam-frontend-components';
import { getAIDetailsKey } from '../components/utils';

const Container = styled.div`
  display: flex;
  flex-direction: column;
  flex-grow: 1;
  max-width: 100%;
  background: #fff;
  border-radius: 8px;
`;
const ErrorMessage = styled.div`
  padding: 20px !important;
  border: 1px solid rgba(37, 56, 88, 0.2);
  border-radius: 4px;
  width: 315px;
  max-width: 100%;
  text-align: left;
`;
const ErrorContainer = styled.div`
  &[aria-hidden='true'] {
    display: none;
  }
  border-radius: 0;
  display: flex;
  text-align: center;
  align-items: center;
  justify-content: center;
  flex-grow: 1;
`;

const cacheTime = 10 * 1000; // 10 seconds

const SessionDetails = memo(
  ({ sessionId, appId, toggleFullScreen, userId, uploadedOn, multiScreenSkippedData, setDetailErrorMessage, userSessionRun }) => {
    const {
      setSessionDetail,
      setSessionBugInfo,
      setNearestSession,
      sessionDetail,
      setSessionLogs,
    } = useSessionTimeLine();
    const { selectedHeaderField } = useSessionHeader();
    const { monthsOfVideosAccessible } = useRestrictionContext()
    const router = useRouter()
    const uxcamuserid = userId || sessionDetail?.userProperty?.uxcamuserid;
    const { 
      urlReducer: { parentType, shareSessionKey },
      appFilter: { dateSegment: dateRange },
      currentOrgReducer: { planLimit },
      screenTimelineReducer: { selectedScreens = [], screenList },
    } = useSelector(state => state);
    // eslint-disable-next-line no-underscore-dangle
    const sessionNumber = useMemo(() => sessionId === sessionDetail?._id ? sessionDetail?.sessionNumber : '', [sessionId, sessionDetail])
    const sessionRun = useMemo(() => sessionNumber || userSessionRun,  [ userSessionRun, sessionNumber ])

    const {
      data: recordingData,
    } = useFetchAppSetting(['appSetting', appId], appId);

  const newScreensFilter = useFeatureFlag( 'new-screens-filter' ) 
  const { getScreenLayoutData} =useScreenLayoutContext()
    // CX-1864 - Start
    // Note: These logic are also in TimelineScreenDropdown but only triggers on Activity tab open
    const {
      data: { data: { data: appScreens = [] } = {} } = {},
    } = useAppScreenList(
      {
        appid: appId,
        attribute: newScreensFilter ? 'screen_name' : 'session_screen_list', 
        date_range: dateRange,
        dropdownLimit: 501,
        filter: [],
        search: '',
        table: 'session'
      },
      { enabled: !shareSessionKey }
    );

    const sessionScreenData = useMemo(() => ({
      data: {
        data: ( sessionDetail?.screenTimeline?.activities || [] )
        .reduce( ( acc, { activityName, endTime, time } ) => {
          const viewtime = endTime - time;
          const existing = acc.find( ( { screenName } ) => screenName === activityName )
          if ( existing ) {
            existing.duration += viewtime
            return acc
          }
          acc.push({
              screenName: activityName,
              duration: viewtime,
          } )
          return acc
        }, [] )
      }
    }), [sessionDetail])

    const sessionScreensList = useMemo(
      () =>
        sessionScreenData
          ? sessionScreenData.data?.data
            .filter((v, index) => v.screenName !== 'Launch' || index !== 0)
            .sort((a, b) => b.duration - a.duration)
          : [],
      [sessionScreenData]
    );
  
    const sessionScreens = useMemo(
      () => sessionScreensList.map((v) => v.screenName),
      [sessionScreensList]
    )
    // CX-1864 - End
    
    const reqSessionDetailBody = useMemo(
      () => ({
        appid: appId,
        sessionid: sessionId,
        uploadedon: uploadedOn
      }),
      [appId, sessionId, uploadedOn]
    );

    const reqBody = useMemo(
      () => ({
        appid: appId,
        sessionid: sessionId,
        uploadedon: uploadedOn
      }),
      [appId, sessionId, uploadedOn]
    );

    const reqNearestSession = useMemo(
      () => ({
        appid: appId,
        sessionid: sessionId,
        uxcamuserid,
        date_range: dateRange,
        usersessionrun: sessionRun
      }),
      [appId, sessionId, uxcamuserid, dateRange, sessionRun]
    );

    const queryKey = useMemo(() => getAIDetailsKey(sessionId), [sessionId]);
    const nextSessionKey = useMemo(
      () => `nextSession${sessionId}`,
      [sessionId]
    );
    const dispatch = useDispatch()

    const { data } = useQuery(
      queryKey,
      () =>
        axios
          .post(`${process.env.PYTHON_API_URL}/ai/sessions/get-details`, reqSessionDetailBody, {
            withCredentials: true,
            credentials: 'include',
          })
          .then(({ data: { data: respData } }) => respData)
          .catch((error) => {
            setSessionDetail(error?.response?.data);
            return error?.response?.data;
          }),
      {
        cacheTime,
        suspense: true,
      }
    );

    const { data: bugInfoData, refetch: refetchBugInfo } =
      useSessionBugInfo(reqBody);
    const { data: appLogsData, refetch: refetchAppLogs } = useSessionAppLogs(reqBody);

    // CX-1864 call get-all-screens api - https://uxcam.slack.com/archives/CAYNR4EHF/p1725972515883519
    const { refetch: refetchSessionScreen } = useSessionScreenList({
        sessionid: sessionId,
        appid: appId,
        uploadedon: uploadedOn
      });

    useEffect(() => {
      refetchBugInfo();
      refetchAppLogs();
      // CX-1864
      if (!shareSessionKey) {
        refetchSessionScreen();
      }
    }, [sessionId]);

    // CX-1864 - Done at top level for case where customer has screens that exceed 500
    useEffect(() => {
      if (appScreens?.length && sessionScreens?.length) {
        let newData = []
        if(screenList.length)
        sessionScreens.forEach(v => {
          if(!screenList.includes(v)) {
            newData = [...newData, v]
          }
        })
        const newScreenList = screenList?.length ? uniq([...screenList, ...sessionScreens]) : uniq([...appScreens, ...sessionScreens])
        const newselected = selectedScreens.length ? uniq([...selectedScreens, ...newData]) : newScreenList
        dispatch(setScreenList(newScreenList));
        dispatch(setSelectedScreens(newselected));
      }
    }, [appScreens, sessionScreens]);


    useEffect(() => {
      if (bugInfoData) {
        setSessionBugInfo(bugInfoData?.data?.data);
      }
    }, [bugInfoData, setSessionBugInfo]);

    useEffect(() => {
      if (appLogsData) {
        setSessionLogs(appLogsData?.data?.data);
      }
    }, [appLogsData, setSessionLogs]);

    const respSessionId = data?.['_id'];

    useEffect(() => {
      data && setSessionDetail({
        ...data,
        isAppLogEnabled: recordingData?.recordAppLog || false,
      });
    }, [sessionId, data, setSessionDetail, recordingData]);


    useEffect(() => {
      if (parentType === 'eventsList')
        dispatch(
          fetchPlanHatApi({
            action: `Played video from ${mappedSegmentType[parentType]} page`,
          })
        );
      dispatch(
        fetchPlanHatApi({
          action: `Viewed session from ${mappedSegmentType[parentType]} page`,
        })
      );
    }, []);

    React.useEffect( () => {
      if ( monthsOfVideosAccessible && isDateOlderThanMonths( data?.time?.sessionUploadedDateTime, monthsOfVideosAccessible ) && planLimit?.videoRetentionTime !== planLimit?.videoPlaybackAccessibleTime ) {
        const newAsPath = router.asPath.replace( router.query.sessionid, '' )
        delete router.query.sessionid;
        router.push(router, newAsPath )
      }
    }, [ router, data, monthsOfVideosAccessible, planLimit ] )

    useEffect(() => {
      setDetailErrorMessage(data?.error?.message);
    }, [data, setDetailErrorMessage])

    const errorVisible = useMemo(() => sessionDetail?.error?.message, [sessionDetail?.error?.message])

    return (
      <>
        {!getScreenLayoutData(parentType)?.isHeaderV2 && 
        !sessionDetail?.error?.message && respSessionId && (
          <SessionDetailsHeader session={data} />
        )}
        {selectedHeaderField === 'sessionVideo' ? (
          <>
            <ErrorContainer aria-hidden={!errorVisible}>
              <ErrorMessage>
                <p
                  dangerouslySetInnerHTML={{
                    __html: sessionDetail?.error?.message,
                  }}
                />
              </ErrorMessage>
            </ErrorContainer>

            {!sessionDetail?.error?.message && respSessionId && (
              <SessionVideo
                appId={appId}
                session={data}
                key={respSessionId}
                toggleFullScreen={toggleFullScreen}
                multiScreenSkippedData={multiScreenSkippedData} />
            )}
          </>
        ) : null}
        {selectedHeaderField?.includes('crash') ? <StackTrace /> : null}
        {selectedHeaderField?.includes('exception') ? <BugTrace /> : null}
        {selectedHeaderField?.includes('UIFreeze') ? <AnrTrace /> : null}
      </>
    );
  }
);

const SessionDetailsLoader = ({
  sessionId,
  appId,
  sessionList,
  userId,
  uploadedOn,
  toggleFullScreen,
  multiScreenSkippedData,
  setDetailErrorMessage
}) => {
  const sessionListItem = useMemo(
    () =>
      sessionList &&
      sessionList.body?.find(({ sessionid }) => sessionid === sessionId),
    [sessionList, sessionId]
  );

  return (
    <Container>
      <SessionLoader
        sessionListItem={sessionListItem}
        toggleFullScreen={toggleFullScreen}
        appId={appId}
        uploadedOn={ uploadedOn }
      >
        <SessionDetails
          toggleFullScreen={toggleFullScreen}
          sessionId={sessionId}
          appId={appId}
          userId={userId}
          uploadedOn={uploadedOn}
          multiScreenSkippedData={multiScreenSkippedData}
          setDetailErrorMessage={setDetailErrorMessage}
          userSessionRun={sessionListItem?.userSessionRun}
        />
      </SessionLoader>
    </Container>
  );
};

export default memo(SessionDetailsLoader);
