export const emailValidateRule = (rule, value, callback) => {
    const email = value?.trim();
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (email?.length && !emailRegex.test(email)) {
      callback('Please enter a valid email address.');
    } else {
      callback();
    }
  };

export const developerEmailValidateRule = (rule, value, callback) => {
    if (!value) {
      callback('Please enter an email address.');
    }
    const email = value?.trim();
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (email?.length && !emailRegex.test(email)) {
      callback('Please enter a valid email address.');
    } else {
      callback();
    }
  };

export const emailsValidateRule = (rule, values, callback) => {
    // const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    
    if (!Array.isArray(values) || values.length === 0) {
      callback('Please enter a valid email address.');
      return;
    }
    if (values.length >= 50) {
      callback('You can only add up to 50 emails.');
      return;
    }
    callback();
  };