import React, { memo, useEffect, useMemo, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { getNewSessionData, getAnrMenu } from 'Utils/helpers/SessionUtils';
import useCustomLabels from 'hooks/useCustomLabels';
import { useSessionTimeLine } from 'components/shared/Sessions/Context';
import { SessionDetails } from 'components/features/aiSessions/components/types';
import UserIcon from 'public/static/session-replay/user.svg';
import { Header, HeaderItem } from './styles';
import SessionCustomLabels from './SessionCustomLabels';
import {
  UserNameComponent,
  LocationHeaderComponent,
  DateHeaderComponent,
  LabelsComponent,
  IssueInfoComponent
} from './SharedHeaderComponents';
import { 
  SessionHeaderProps, 
  CustomLabel,
  SessionDetail,
} from './types';

const SessionHeader: React.FC<SessionHeaderProps> = ({ session }) => {
  const {
    appFilter,
    urlReducer: urlQuery,
  } = useSelector((state: any) => state);
  const { parentType, appId } = urlQuery;
  const pageSegment = useMemo(() => {
    if (parentType === 'issues') {
      return appFilter.issue?.segment || [];
    }
    if (parentType === 'eventsList') {
      return appFilter.event?.segment || [];
    }
    return appFilter.session?.segment || [];
  }, [appFilter, parentType]);
  const {
    megaFilterCustomLabels: customLabels,
  } = useCustomLabels();
  const customLabelsArray = useMemo(()=>customLabels.map((item: CustomLabel) => item.name), [ customLabels] ) ;

  const { sessionDetail, sessionBugInfo } = useSessionTimeLine();
  const [labelSession, setLabelSession] = useState<string[]>([]);
  const [showCustomLabel, setShowCustomLabel] = useState(false);

  const sessionDetails = useMemo(
    () => getNewSessionData(session, parentType) as SessionDetails,
    [session, parentType]
  );

  const sessionLabel = sessionDetails?.customLabel;
  const isCrashLog = (sessionDetail as SessionDetail)?.isCrashedLog || false;
  const totalBugs = sessionBugInfo || [];
  const anrMenu = useMemo(() => getAnrMenu(sessionDetail) || [], [sessionDetail]);

  useEffect(() => {
    if ( [ 'sessionsList', 'eventsList', 'aiSessionsList' ].includes( parentType ) ) {
      const result = sessionLabel?.filter(
        (label: string) => customLabelsArray.indexOf(label) >= 0
      );
      setLabelSession(result || []);
    } else {
      setLabelSession(sessionLabel || []);
    }
  }, [sessionLabel, customLabels, parentType, customLabelsArray]);

  return (
    <>
      <Header>
        <HeaderItem data-intercom-target="Session User Id" className="labels-nav">
          <UserIcon className='user-icon'/>
          <UserNameComponent 
            sessionDetails={sessionDetails}
            appId={appId}
            urlQuery={urlQuery}
            parentType={parentType}
          />
        </HeaderItem>
        
        <LocationHeaderComponent 
          sessionDetails={sessionDetails}
          pageSegment={pageSegment}
        />
        
        <DateHeaderComponent 
          sessionDetails={sessionDetails}
          pageSegment={pageSegment}
          parentType={parentType}
        />
        
        <LabelsComponent 
          labelSession={labelSession}
          showCustomLabel={showCustomLabel}
          setShowCustomLabel={setShowCustomLabel}
        />

        <IssueInfoComponent 
          isCrashLog={isCrashLog}
          totalBugs={totalBugs}
          anrMenu={anrMenu}
        />
      </Header>
      {showCustomLabel && (
        <SessionCustomLabels
        //   className="session-label-expand"
          setShowCustomLabel={setShowCustomLabel}
        />
      )}
    </>
  );
};

export default memo(SessionHeader); 