import React from 'react';
import styled from 'styled-components';
import { useSelector } from 'react-redux';
import VideoControls from '../VideoControls';
import { useScreenLayoutContext } from '../../Context';
import SessionDetailsHeader from '../Header/SessionDetailsHeader';

const FallbackContainer = styled.div`
  display: flex;
  flex-direction: column;
  flex-grow: 1;
`;

const FallbackInner = styled.div`
  flex-grow: 1;
  position: relative;
`;

const SessionLoader = ({ sessionListItem, children }) => {
  const videoRef = React.useRef();
  const { getScreenLayoutData} =useScreenLayoutContext()
    const { urlReducer: { parentType }} = useSelector(state => state);

  const Fallback = React.useMemo(() => {
    if (sessionListItem) {
      return (
        <FallbackContainer>
         { !getScreenLayoutData(parentType).isHeaderV2 && <SessionDetailsHeader session={sessionListItem} /> }
          <FallbackInner>
            <div />
          </FallbackInner>
          <VideoControls screens={[]} videoRef={videoRef} />
        </FallbackContainer>
      );
    }

    return null;
  }, [sessionListItem, getScreenLayoutData, parentType]);

  return <React.Suspense fallback={Fallback}>{children}</React.Suspense>;
};

export default React.memo(SessionLoader);
